#pragma once

#include <array>

#include "point_lights.hpp"
#include "shared/common/ffp_state.hpp"

namespace comp::game::ffx_lights
{
	// Lights for the effects the game draws without one, from rtx_comp\ffx_lights.tsv (generated by
	// scripts\gen_ffx_tables.py from the effect analysis: the developers' own effect-light rule applied to
	// every FFX without a light node). Every live instance of a listed effect (ffx_instances) gets its
	// light at the instance's position. An instance can far outlive what it shows (Moonlight Butterfly's
	// attack effect, 0.5 s of visuals, at age 300 s and more), so a brief effect is lit only for its visual
	// lifetime, or while its emitters run, and then fades out; a persistent one until only leftovers remain.
	// game_lights draws them as the "Unlit effects" kind.
	struct entry
	{
		float r, g, b;             // game units, colour x alpha x 2.55 like the game's light nodes
		float dwindle_begin;
		float dwindle_end;
		bool planar;               // its brightest sprite lies in the effect's own plane (messages, signs)
		bool persistent;           // lasts while its map, object, owner or status lasts
		bool impact = false; // a projectile's hit effect: its brightness is its fade, whatever its children do
		// What the sprite the light was measured from gives off over its life, from the effect's colour and size curves.
		float fade_life = 0.0f;
		std::array<float, 12> fade {};
		float fade_peak = 0.0f; // seconds into fade_life where it is brightest
		float visual_life;         // seconds its brightest sprites last
		char confidence;           // 'h', 'm' or 'l'
		std::string category;
	};

	// The table entry for an effect, or nullptr when it gets no light.
	const entry* find(int ffx_id);
	int table_size();

	// Once per frame, from game_lights: a light per live listed effect instance within reach of the
	// camera. Slots are unique per instance while it lives; ffx_id / ffx_top_id name the effect.
	// covers are the map's own lights (MSB bank lights, bank entities, map_lights stand-ins): a persistent
	// effect with one of them within 3 m is the flame that light stands for, and gets none.
	const std::vector<point_lights::light>& collect(const std::vector<const point_lights::light*>& covers, float colour_scale);

	// The light level (0..1) an instance has now, below 0 when it has none: what a capture records with it (ffx_instances::snapshot).
	float level_of(unsigned address);

	// What an effect instance drew in the last complete frame, itself and every effect under it: the additive sprites the game's
	// particle draws issued for them (fx_draw_owner), summed. The link between an effect's light and its own sprites.
	struct drawn_light
	{
		float r = 0.0f, g = 0.0f, b = 0.0f; // sum of sprite colour x area (m2), per channel
		float area = 0.0f;                  // m2 of sprites
		int sprites = 0;
		float extent = 0.0f;                // metres across the box that holds their centres
		float spread = 0.0f;                // metres: twice the light-weighted RMS distance of the sprites from their own centre
		float centre[3] = {};               // that centre
	};
	drawn_light drawn_by(unsigned instance);
	// Writes rtx_comp\ffx_drawn.tsv: every top-level effect and every effect with a light row that drew something, what it drew,
	// its table light, and the game's own effect lights of the frame (live proxy.Lights.EffectDrawDump).
	void dump_drawn();

	// Fire effect lights sized by their own flame. The game gives an effect's light one fixed reach whatever the effect draws
	// (its own light nodes: 1.2 m for the Kiln cutscene's brazier fire, 4.8 m for a bonfire), and the table's rows were fitted from
	// a single particle. So a fire light's reach is the spread of the flame its effect draws (drawn_light::spread, smoothed) times
	// [Lights] EffectSizeReach, 2.68: a wall torch's flame spreads 1.41 m and its light reaches 3.78 m (frame_20261111_142503,
	// 143022). Kiln embers then reach 5.6-7 m (table 5), the brazier fire 7.2 m, the fire round the character 4 m, the small flames
	// on a hand 0.5-0.8 m. Only warm lights (r >= g >= b, r >= 1.6 b): other effects keep what they have. Colour and strength stay.
	// Live: proxy.Lights.EffectSize (0 off), EffectSizeReach, EffectSizeMin, EffectSizeMax, EffectSizeGame.
	//
	// The spread is one value per effect, not taken from each instance as it is drawn: the game draws only part of an effect's
	// emitters depending on the view (the same wall torch effect measured 1.41 m in the Burg and 0.70 m across the Kiln's hall),
	// and a light must not change its reach as the camera turns to its flame. It comes from rtx_comp\ffx_sizes.tsv, shipped:
	// the largest measure of each effect over the captures that show it (scripts/gen_ffx_sizes.py), fire lights only. An effect
	// that is not in it keeps what it has, so nothing changes during play and nothing is written.
	// [Lights] EffectSizeLearn (off; live) lets the game add what it measures itself: the largest settled spread of any instance,
	// kept in rtx_comp\ffx_sizes_learned.tsv. Lights then do change once, when their effect is first seen whole.
	//
	// A table light is only made longer, as the game's own are: the three effects of the first table whose flame says less than
	// their table reach (90012 3.78 -> 1.98 m, 41803 1.5 -> 0.88 m, 41811 3.05 -> 2.57 m) gave no capture where shorter is nearer
	// the game (the sitting character went from 43.7 to 42.8 of 255, the game's 53.7). [Lights] EffectSizeShrink=1 (live
	// proxy.Lights.EffectSizeShrink) lets the flame shorten them too.
	//
	// The reach for a light of this colour that belongs to an instance of `effect` (the effect whose instance tree is measured),
	// 0 when the rule does not apply (off, not warm, nothing known yet). `instance` (0: none at hand) adds its measure to what is known.
	float sized_reach(unsigned instance, int effect, float r, float g, float b);
	// The rule's two switches as they stand, for F4 > Lights: reach from the flame ([Lights] EffectSize) and raised to the flame's
	// centre ([Lights] EffectSizeLift). Set through set_follow_option("Lights.EffectSize" / "Lights.EffectSizeLift", 0 or 1).
	bool size_rule_enabled();
	bool size_lift_enabled();

	// The flicker of a game effect light whose reach the flame's size makes longer. The game flickers such a light hard and keeps
	// it short: the Kiln brazier's cutscene light (41812) went 1.09, 2.14, 1.32, 0.24, 1.09, 0.87 in six captures of one scene
	// (frame_20261111_174512 to 174621), with a reach of 1.06 to 1.83 m, while the light its fire's sprites draw changed by about
	// a fifth between captures of the same view and not in step with it. Made 9 m long it took the whole scene from lit to dark:
	// (0.24 / 2.14)^2.2 is a 120th of the light. So a lengthened light is held at its own running mean (EffectFlickerSeconds, 1 s)
	// and keeps this share of its swing about that mean, as a power: 0.15 turns the 8.8-fold swing into 1.4-fold, about what the
	// sprites do. [Lights] EffectFlicker (0.15; 1 = the game's flicker as it is, 0 = steady), live proxy.Lights.EffectFlicker.
	// Lights the rule does not lengthen keep the game's flicker over the game's reach.
	// The mean starts from what the same effect's light last settled at (this session), or from the first sample when the
	// effect is new, and is a plain average for its first EffectFlickerSeconds, so one odd first sample does not hold it.
	// A light under a twentieth of its mean is fading out, not flickering (the brazier's lowest was a fifth): it goes by the
	// game's value there, blending in from a fifth down.
	void steady_flicker(int slot, int effect, float& r, float& g, float& b);
	float effect_flicker();

	// The bonfire's light. Every bonfire runs the light-only effect 90006 at its origin, and the game puts that effect's light
	// node at a random point 0.30 m from the origin, chosen anew each time the effect starts: over six bonfires in captures of
	// 2026-11-11 it stood 0.26 m above, 0.27 m below, 0.23 above, 0.18 below, 0.29 above and 0.24 below the origin, and 0.07 to
	// 0.24 m to one side (frame_20261111_184844 to 185116, 142503). Its lights cast no shadows, so that never showed. Path
	// traced, a light under the ash lights nothing (the bonfire looks unlit) and one to the side throws the sword's and the
	// pile's shadows a different way at every bonfire. The fire itself is the same everywhere: its sprites' light sits on the
	// axis, 0.15 to 0.28 m over the origin. So the light is put on the bonfire's axis at BonfireLightHeight (0.22 m) over
	// the origin of the effect instance it belongs to. [Lights] BonfireLightCentre (1), BonfireLightHeight; both live.
	// The Kiln of the First Flame's bonfire, where the fire is linked, burns the largest flame (90004, seen in 25 captures and
	// at no other bonfire): its fire is drawn by the cutscene's effects in a deep bowl. At 0.22 m its light stays inside the
	// bowl (every level ray is blocked to +0.2 m, the bowl wall 0.56 m off; free from +0.4 m); half of its fire's light is
	// under +0.71 m. So it has a height of its own, BonfireLightHeightLarge (0.7 m), also live.
	// False when the light is no bonfire's, the rule is off, or its effect instance is not found (then it stays where it is).
	// origin_y (optional): the height of the bonfire's origin, which is what the light is keyed by.
	bool bonfire_light_place(const point_lights::light& l, float out[3], float* origin_y = nullptr);
	bool bonfire_light_centred();
	float bonfire_light_height();
	float bonfire_light_height_large();
	// How far above its effect's origin such a light belongs: the height of the flame's light-weighted centre over the origin,
	// learned with the spread (the same instance's). The game puts an effect's light at the origin, which for a brazier or a
	// sconce is inside the bowl: its lights cast no shadows, so that never showed; path traced, the bowl shadows everything
	// but the sky above it (frame_20261111_142320: reach 1.2 to 9 m changed nothing on the bowl or the knight beside it).
	// 0 when unknown or the rule is off, or under half a metre (a wall torch's 0.2 m gains nothing, and a moved light no longer
	// matches the edits saved for its place); never down, at most 2.5 m up. The callers use it for steady flames only: persistent
	// table effects and the game's own effect lights. [Lights] EffectSizeLift, live proxy.Lights.EffectSizeLift: on by default
	// (the user's call after flipping it in the game, 2026-11-11; it was off for some hours that day).
	// The centre it goes to is the light-weighted mean of everything the effect draws, sparks and all: for the Kiln brazier's
	// cutscene fire (41812) 1.27 m over the effect's origin, which puts that light 1.5 m over where the game has it, above three
	// quarters of the fire's light and above the picture's top edge in frame_20261111_142320: higher than the fire's middle.
	float sized_lift(int effect, float r, float g, float b);
	// How far the light in this slot was raised (0: not). What is saved per light goes by its place (game_lights' own keys):
	// that must stay the place the game has it at, or a new size table would orphan the edits made to a lifted light.
	void note_lift(int slot, float lift);
	float lift_of(int slot);
	// The same for one of the game's own effect lights (a light node in an effect, point_lights::light with an ffx id): by the
	// top-level instance of its effect nearest to it. Game lights are only ever extended by the caller: a bonfire's flame is a
	// mesh, which the sprite measure does not see. `lift` (optional): how far to raise the light so that it stands at the
	// flame's centre, measured from where the light node is, not added blind: a node the effect already holds up in its
	// flame is raised by what is missing, or not at all. 0 when the light's instance is not found.
	float sized_reach_at(const point_lights::light& l, float* lift = nullptr);

	// The particles drawn this frame: lights that follow their effect's sprites (Tomb of the Giants' lantern halos) take their level from them.
	void observe_sprites(const shared::common::ffp_state::sprite_point* points, UINT count);

	// Live options Lights.FollowRiseSeconds, Lights.FollowFallSeconds, Lights.FollowFullAlpha: false for any other key.
	bool set_follow_option(const std::string& key, float value);

}
